// SPDX-License-Identifier: MIT
//
// PoC 13F: run exactly 10,000 deterministic UINT8[481] frames through the
// sealed Erf NBG. Inputs are generated by one fixed xorshift32 stream and
// cumulative input/output digests are reported every 1,000 frames. There is
// no configurable model, seed, tensor, iteration, output, retry, recovery, or
// direct-device interface.

#include "tim/vx/context.h"
#include "tim/vx/graph.h"
#include "tim/vx/ops/nbg.h"
#include "tim/vx/tensor.h"
#include "tim/vx/types.h"

#include <algorithm>
#include <array>
#include <cerrno>
#include <csignal>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <memory>
#include <sys/prctl.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <vector>

struct ChipIdentityEx {
    uint32_t chip_model;
    uint32_t chip_revision;
    uint32_t chip_product_id;
    uint32_t customer_id;
    uint32_t chip_eco_id;
    uint32_t reserved;
    uint64_t chip_flags;
};

static_assert(sizeof(ChipIdentityEx) == 0x20, "unexpected identity ABI");

extern "C" int gcoHAL_QueryChipIdentityEx(
    void* hal,
    uint32_t identity_size,
    ChipIdentityEx* identity);

namespace {

constexpr size_t kSoakFrames = 10000;
constexpr size_t kCheckpointFrames = 1000;
constexpr size_t kFrameWidth = 481;
constexpr size_t kExpectedNbgBytes = 5840;
constexpr size_t kCanaryBytes = 32;
constexpr uint8_t kCanaryValue = 0xa5;
constexpr uint32_t kInputSeed = 0x5733130fU;
constexpr uint64_t kFnvOffsetBasis = UINT64_C(0xcbf29ce484222325);
constexpr uint64_t kFnvPrime = UINT64_C(0x100000001b3);
constexpr uint32_t kWaveChipModel = 0x00009000U;
constexpr uint32_t kWaveProductId = 0x1000000eU;
constexpr uint32_t kWaveNbgVersion = 0x00020000U;
constexpr unsigned int kWatchdogSeconds = 30;
constexpr char kExpectedLibraryPath[] =
    "/tmp/wave-npu-poc13f/lib:/usr/lib";
constexpr char kExpectedSdkDirectory[] = "/usr";
constexpr char kNbgPath[] =
    "/tmp/wave-npu-poc13f/model/erf-mask.nbg";
constexpr char kForbiddenClcPath[] =
    "/tmp/wave-npu-poc13f/lib/libCLC.so";

void WatchdogHandler(int) {
    constexpr char kMessage[] =
        "ERF_SOAK status=TIMEOUT mode=soak-10000 exit=124\n";
    const ssize_t message_bytes =
        write(STDERR_FILENO, kMessage, sizeof(kMessage) - 1);
    (void)message_bytes;
    _exit(124);
}

uint32_t ReadLe32(const uint8_t* data) {
    return static_cast<uint32_t>(data[0]) |
           (static_cast<uint32_t>(data[1]) << 8U) |
           (static_cast<uint32_t>(data[2]) << 16U) |
           (static_cast<uint32_t>(data[3]) << 24U);
}

uint64_t UpdateFnv1a64(
    uint64_t value, const uint8_t* data, size_t bytes) {
    for (size_t index = 0; index < bytes; ++index) {
        value ^= data[index];
        value *= kFnvPrime;
    }
    return value;
}

uint32_t NextXorshift32(uint32_t value) {
    value ^= value << 13U;
    value ^= value >> 17U;
    value ^= value << 5U;
    return value;
}

bool PathIsAbsent(const char* path) {
    struct stat path_stat {};
    if (lstat(path, &path_stat) == 0) {
        return false;
    }
    return errno == ENOENT;
}

bool EnvironmentIsFixed() {
    const char* const library_path = std::getenv("LD_LIBRARY_PATH");
    const char* const sdk_directory = std::getenv("VIVANTE_SDK_DIR");
    if (library_path == nullptr ||
        std::strcmp(library_path, kExpectedLibraryPath) != 0 ||
        sdk_directory == nullptr ||
        std::strcmp(sdk_directory, kExpectedSdkDirectory) != 0) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: fixed environment mismatch\n");
        return false;
    }
    if (std::getenv("LD_PRELOAD") != nullptr ||
        std::getenv("LD_AUDIT") != nullptr ||
        std::getenv("VSIMULATOR_CONFIG") != nullptr) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: interposition and simulator "
            "variables must be unset\n");
        return false;
    }
    if (!PathIsAbsent(kForbiddenClcPath)) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: isolated CLC path must be absent\n");
        return false;
    }
    return true;
}

bool ReadFixedNbg(std::vector<uint8_t>* nbg) {
    const int fd = open(kNbgPath, O_RDONLY | O_CLOEXEC | O_NOFOLLOW);
    if (fd < 0) {
        std::fprintf(
            stderr, "open(%s): %s\n", kNbgPath, std::strerror(errno));
        return false;
    }
    struct stat model_stat {};
    if (fstat(fd, &model_stat) != 0 ||
        !S_ISREG(model_stat.st_mode) ||
        (model_stat.st_mode & 0777) != 0444 ||
        model_stat.st_size != static_cast<off_t>(kExpectedNbgBytes)) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: fixed NBG metadata mismatch\n");
        close(fd);
        return false;
    }
    nbg->assign(kExpectedNbgBytes, 0);
    size_t offset = 0;
    while (offset < nbg->size()) {
        const ssize_t count =
            read(fd, nbg->data() + offset, nbg->size() - offset);
        if (count < 0) {
            if (errno == EINTR) {
                continue;
            }
            std::fprintf(
                stderr,
                "read(%s): %s\n",
                kNbgPath,
                std::strerror(errno));
            close(fd);
            return false;
        }
        if (count == 0) {
            std::fprintf(
                stderr, "wave_npu_soak_erf_mask: short NBG read\n");
            close(fd);
            return false;
        }
        offset += static_cast<size_t>(count);
    }
    uint8_t extra = 0;
    if (read(fd, &extra, 1) != 0 || close(fd) != 0) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: NBG close/length check failed\n");
        return false;
    }
    return std::memcmp(nbg->data(), "VPMN", 4) == 0 &&
           ReadLe32(nbg->data() + 4) == kWaveNbgVersion &&
           ReadLe32(nbg->data() + 8) == kWaveProductId;
}

uint64_t ElapsedMicroseconds(
    const struct timespec& started,
    const struct timespec& finished) {
    const int64_t seconds =
        static_cast<int64_t>(finished.tv_sec) -
        static_cast<int64_t>(started.tv_sec);
    const int64_t nanoseconds =
        static_cast<int64_t>(finished.tv_nsec) -
        static_cast<int64_t>(started.tv_nsec);
    return static_cast<uint64_t>(
        seconds * INT64_C(1000000) + nanoseconds / INT64_C(1000));
}

bool CanariesAreIntact(
    const std::array<uint8_t, kFrameWidth + 2 * kCanaryBytes>& buffer) {
    return std::all_of(
               buffer.begin(),
               buffer.begin() + kCanaryBytes,
               [](uint8_t value) { return value == kCanaryValue; }) &&
           std::all_of(
               buffer.end() - kCanaryBytes,
               buffer.end(),
               [](uint8_t value) { return value == kCanaryValue; });
}

void PrintDefinition() {
    std::puts(
        "{\"schema_version\":1,\"mode\":\"soak-10000\","
        "\"model\":\"/tmp/wave-npu-poc13f/model/erf-mask.nbg\","
        "\"model_bytes\":5840,\"model_sha256\":"
        "\"96447d6afd63a7c349bbd80f0af99150c89ef24ed7f1ef66ab285075362e6c94\","
        "\"operation\":\"NBG\",\"input\":{\"type\":\"UINT8\","
        "\"shape\":[481],\"scale\":0.03125,\"zero_point\":128,"
        "\"generator\":\"xorshift32\",\"seed\":\"0x5733130f\"},"
        "\"output\":{\"type\":\"UINT8\",\"shape\":[481],"
        "\"scale\":0.0078125,\"zero_point\":128},\"frames\":10000,"
        "\"checkpoint_frames\":1000,\"compile_count\":1,"
        "\"run_count\":10000,\"output_canary_bytes\":32,"
        "\"executes_graph\":true}");
}

}  // namespace

int main(int argc, char** argv) {
    if (argc == 2 && std::strcmp(argv[1], "--describe") == 0) {
        PrintDefinition();
        return 0;
    }
    if (argc != 2 || std::strcmp(argv[1], "--soak-10000") != 0) {
        std::fprintf(stderr, "usage: %s --soak-10000\n", argv[0]);
        std::fprintf(stderr, "       %s --describe\n", argv[0]);
        return 10;
    }
    if (!EnvironmentIsFixed()) {
        return 12;
    }
    if (prctl(PR_SET_PDEATHSIG, SIGKILL) != 0 || getppid() == 1) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: parent-death gate failed\n");
        return 17;
    }
    struct sigaction watchdog_action {};
    watchdog_action.sa_handler = WatchdogHandler;
    sigemptyset(&watchdog_action.sa_mask);
    if (sigaction(SIGALRM, &watchdog_action, nullptr) != 0) {
        std::fprintf(
            stderr,
            "wave_npu_soak_erf_mask: watchdog setup failed: %s\n",
            std::strerror(errno));
        return 18;
    }
    alarm(kWatchdogSeconds);

    std::vector<uint8_t> nbg;
    if (!ReadFixedNbg(&nbg)) {
        return 13;
    }
    auto context = tim::vx::Context::Create();
    if (!context) {
        std::fprintf(stderr, "wave_npu_soak_erf_mask: context failed\n");
        return 1;
    }
    ChipIdentityEx identity {};
    const int identity_status = gcoHAL_QueryChipIdentityEx(
        nullptr,
        static_cast<uint32_t>(sizeof(identity)),
        &identity);
    if (identity_status != 0 ||
        identity.chip_model != kWaveChipModel ||
        identity.customer_id != kWaveProductId) {
        std::fprintf(
            stderr, "wave_npu_soak_erf_mask: identity mismatch\n");
        return 15;
    }
    std::printf(
        "IDENTITY chip_model=0x%08x chip_revision=0x%08x "
        "chip_product_id=0x%08x chip_eco_id=0x%08x "
        "customer_id=0x%08x reserved=0x%08x flags=0x%016llx\n",
        identity.chip_model,
        identity.chip_revision,
        identity.chip_product_id,
        identity.chip_eco_id,
        identity.customer_id,
        identity.reserved,
        static_cast<unsigned long long>(identity.chip_flags));
    std::fflush(stdout);

    auto graph = context->CreateGraph();
    if (!graph) {
        std::fprintf(stderr, "wave_npu_soak_erf_mask: graph failed\n");
        return 2;
    }
    const tim::vx::ShapeType shape{481};
    const tim::vx::Quantization input_quantization(
        tim::vx::QuantType::ASYMMETRIC, 0.03125F, 128);
    const tim::vx::Quantization output_quantization(
        tim::vx::QuantType::ASYMMETRIC, 0.0078125F, 128);
    const tim::vx::TensorSpec input_spec(
        tim::vx::DataType::UINT8,
        shape,
        tim::vx::TensorAttribute::INPUT,
        input_quantization);
    const tim::vx::TensorSpec output_spec(
        tim::vx::DataType::UINT8,
        shape,
        tim::vx::TensorAttribute::OUTPUT,
        output_quantization);
    auto input = graph->CreateTensor(input_spec);
    auto output = graph->CreateTensor(output_spec);
    if (!input || !output) {
        std::fprintf(stderr, "wave_npu_soak_erf_mask: tensors failed\n");
        return 3;
    }
    auto nbg_operation = graph->CreateOperation<tim::vx::ops::NBG>(
        reinterpret_cast<const char*>(nbg.data()), 1, 1);
    if (!nbg_operation) {
        std::fprintf(stderr, "wave_npu_soak_erf_mask: NBG op failed\n");
        return 4;
    }
    nbg_operation->BindInput(input).BindOutput(output);

    std::array<uint8_t, kFrameWidth> input_bytes {};
    uint32_t random_state = kInputSeed;
    uint64_t input_fnv = kFnvOffsetBasis;
    uint64_t output_fnv = kFnvOffsetBasis;
    uint64_t total_run_us = 0;
    uint64_t minimum_run_us = UINT64_MAX;
    uint64_t maximum_run_us = 0;
    bool compiled = false;
    for (size_t frame_index = 0;
         frame_index < kSoakFrames;
         ++frame_index) {
        for (uint8_t& value : input_bytes) {
            random_state = NextXorshift32(random_state);
            value = static_cast<uint8_t>(random_state & 0xffU);
        }
        input_fnv = UpdateFnv1a64(
            input_fnv, input_bytes.data(), input_bytes.size());
        if (!input->CopyDataToTensor(
                input_bytes.data(), input_bytes.size())) {
            std::fprintf(
                stderr,
                "wave_npu_soak_erf_mask: input copy failed at %zu\n",
                frame_index);
            return 5;
        }
        if (!compiled) {
            if (!graph->Compile()) {
                std::fprintf(
                    stderr, "wave_npu_soak_erf_mask: compile failed\n");
                return 6;
            }
            compiled = true;
        }
        struct timespec started {};
        struct timespec finished {};
        if (clock_gettime(CLOCK_MONOTONIC, &started) != 0 ||
            !graph->Run() ||
            clock_gettime(CLOCK_MONOTONIC, &finished) != 0) {
            std::fprintf(
                stderr,
                "wave_npu_soak_erf_mask: run failed at %zu\n",
                frame_index);
            return 7;
        }
        const uint64_t elapsed =
            ElapsedMicroseconds(started, finished);
        total_run_us += elapsed;
        minimum_run_us = std::min(minimum_run_us, elapsed);
        maximum_run_us = std::max(maximum_run_us, elapsed);

        std::array<uint8_t, kFrameWidth + 2 * kCanaryBytes> observed {};
        observed.fill(kCanaryValue);
        uint8_t* const output_bytes = observed.data() + kCanaryBytes;
        if (!output->CopyDataFromTensor(output_bytes)) {
            std::fprintf(
                stderr,
                "wave_npu_soak_erf_mask: output copy failed at %zu\n",
                frame_index);
            return 8;
        }
        if (!CanariesAreIntact(observed)) {
            std::fprintf(
                stderr,
                "wave_npu_soak_erf_mask: canary changed at %zu\n",
                frame_index);
            return 9;
        }
        output_fnv = UpdateFnv1a64(
            output_fnv, output_bytes, kFrameWidth);
        if ((frame_index + 1) % kCheckpointFrames == 0) {
            std::printf(
                "CHECKPOINT frames=%zu input_fnv1a64=0x%016llx "
                "output_fnv1a64=0x%016llx\n",
                frame_index + 1,
                static_cast<unsigned long long>(input_fnv),
                static_cast<unsigned long long>(output_fnv));
            std::fflush(stdout);
        }
    }

    nbg_operation.reset();
    output.reset();
    input.reset();
    graph.reset();
    context.reset();
    alarm(0);
    std::printf(
        "ERF_SOAK status=PASS mode=soak-10000 frames=10000 "
        "bytes_per_frame=481 compile_count=1 run_count=10000 "
        "checkpoints=10 canaries=PASS total_run_us=%llu "
        "min_run_us=%llu max_run_us=%llu "
        "input_fnv1a64=0x%016llx output_fnv1a64=0x%016llx\n",
        static_cast<unsigned long long>(total_run_us),
        static_cast<unsigned long long>(minimum_run_us),
        static_cast<unsigned long long>(maximum_run_us),
        static_cast<unsigned long long>(input_fnv),
        static_cast<unsigned long long>(output_fnv));
    return 0;
}
